// The agent normally returns plain text. It can also return fenced JSON if the
// system prompt is changed, so unwrap that case rather than showing raw braces.
const raw = String($json.response ?? '').trim();

let text = raw;
const fenced = raw.match(/^```(?:json)?\s*([\s\S]*?)```$/);
if (fenced) {
  const inner = fenced[1].trim();
  try {
    const parsed = JSON.parse(inner);
    text = typeof parsed === 'string' ? parsed : (parsed.output ?? parsed.text ?? parsed.response ?? inner);
  } catch {
    text = inner;
  }
}

if (!text) {
  text = 'The agent returned an empty response. This is usually a transient service error - please send the message again.';
}

return [{
  json: {
    output: text,
    customerId: $('Set Customer Identity').item.json.customerId,
    sessionSource: $json.sessionSource ?? null,
    latencyMs: $json.latencyMs ?? null,
  },
}];
